#!/usr/bin/env python3

from __future__ import annotations

import ast
import json
from pathlib import Path


PLANETS = (
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
)


def operational_oracle(first: str, second: str) -> tuple[str, ...]:
    if first not in PLANETS or second not in PLANETS:
        return ()
    first_index = PLANETS.index(first)
    second_index = PLANETS.index(second)
    if first_index < second_index:
        return PLANETS[first_index + 1 : second_index]
    return PLANETS[second_index + 1 : first_index]


def summary_index(value: str) -> int:
    for index, planet in enumerate(PLANETS):
        if value == planet:
            return index
    return -1


def summary_between_indices(first: int, second: int) -> tuple[str, ...]:
    if first < 0 or second < 0:
        return ()
    if first < second:
        return tuple(PLANETS[index] for index in range(first + 1, second, 1))
    return tuple(PLANETS[index] for index in range(second + 1, first, 1))


def summary_model(first: str, second: str) -> tuple[str, ...]:
    return summary_between_indices(summary_index(first), summary_index(second))


def mutation_include_first(first: str, second: str) -> tuple[str, ...]:
    i, j = summary_index(first), summary_index(second)
    if i < 0 or j < 0:
        return ()
    return PLANETS[min(i, j) : max(i, j)]


def mutation_reverse_output(first: str, second: str) -> tuple[str, ...]:
    return tuple(reversed(summary_model(first, second)))


def mutation_invalid_full(first: str, second: str) -> tuple[str, ...]:
    if summary_index(first) < 0 or summary_index(second) < 0:
        return PLANETS
    return summary_model(first, second)


def ast_shape_checks() -> dict[str, bool]:
    module = ast.parse(Path("/reference/k-proof/solution.py").read_text())
    function = module.body[0]
    assert isinstance(function, ast.FunctionDef)
    body = function.body
    planets_assignment = body[0]
    invalid_if = body[1]
    index1_assignment = body[2]
    index2_assignment = body[3]
    ascending_if = body[4]
    descending_return = body[5]
    tuple_values = tuple(
        element.value for element in planets_assignment.value.elts
    )

    def is_index_call(statement: ast.Assign, variable: str, argument: str) -> bool:
        call = statement.value
        return (
            isinstance(call, ast.Call)
            and isinstance(call.func, ast.Attribute)
            and isinstance(call.func.value, ast.Name)
            and call.func.value.id == "planets"
            and call.func.attr == "index"
            and len(call.args) == 1
            and isinstance(call.args[0], ast.Name)
            and call.args[0].id == argument
            and isinstance(statement.targets[0], ast.Name)
            and statement.targets[0].id == variable
        )

    def slice_shape(statement: ast.Return, low_name: str, high_name: str) -> bool:
        value = statement.value
        if not isinstance(value, ast.Subscript) or not isinstance(value.slice, ast.Slice):
            return False
        lower = value.slice.lower
        upper = value.slice.upper
        return (
            isinstance(value.value, ast.Name)
            and value.value.id == "planets"
            and isinstance(lower, ast.BinOp)
            and isinstance(lower.op, ast.Add)
            and isinstance(lower.left, ast.Name)
            and lower.left.id == low_name
            and isinstance(lower.right, ast.Constant)
            and lower.right.value == 1
            and isinstance(upper, ast.Name)
            and upper.id == high_name
            and value.slice.step is None
        )

    invalid_test = invalid_if.test
    return {
        "one_bf_function": len(module.body) == 1 and function.name == "bf",
        "two_parameters": [argument.arg for argument in function.args.args]
        == ["planet1", "planet2"],
        "exact_planet_tuple": tuple_values == PLANETS,
        "invalid_guard_is_or": isinstance(invalid_test, ast.BoolOp)
        and isinstance(invalid_test.op, ast.Or)
        and len(invalid_test.values) == 2
        and all(
            isinstance(test, ast.Compare)
            and len(test.ops) == 1
            and isinstance(test.ops[0], ast.NotIn)
            for test in invalid_test.values
        ),
        "invalid_returns_empty_tuple": isinstance(invalid_if.body[0], ast.Return)
        and isinstance(invalid_if.body[0].value, ast.Tuple)
        and invalid_if.body[0].value.elts == [],
        "index1_exact": is_index_call(index1_assignment, "index1", "planet1"),
        "index2_exact": is_index_call(index2_assignment, "index2", "planet2"),
        "ascending_guard_exact": isinstance(ascending_if.test, ast.Compare)
        and isinstance(ascending_if.test.ops[0], ast.Lt),
        "ascending_slice_exact": slice_shape(
            ascending_if.body[0], "index1", "index2"
        ),
        "descending_slice_exact": slice_shape(
            descending_return, "index2", "index1"
        ),
    }


def main() -> None:
    samples = PLANETS + ("Pluto", "", "Mércury")
    comparisons = []
    for first in samples:
        for second in samples:
            expected = operational_oracle(first, second)
            observed = summary_model(first, second)
            comparisons.append(
                {
                    "first": first,
                    "second": second,
                    "operational": expected,
                    "summary": observed,
                    "match": expected == observed,
                }
            )
    mutation_witnesses = {
        "include_endpoint": {
            "input": ["Earth", "Mercury"],
            "expected": operational_oracle("Earth", "Mercury"),
            "mutated": mutation_include_first("Earth", "Mercury"),
        },
        "reverse_output": {
            "input": ["Mercury", "Uranus"],
            "expected": operational_oracle("Mercury", "Uranus"),
            "mutated": mutation_reverse_output("Mercury", "Uranus"),
        },
        "invalid_nonempty": {
            "input": ["Pluto", "Mercury"],
            "expected": operational_oracle("Pluto", "Mercury"),
            "mutated": mutation_invalid_full("Pluto", "Mercury"),
        },
    }
    ast_checks = ast_shape_checks()
    checks = {
        "source_ast_matches_frozen_algorithm": all(ast_checks.values()),
        "summary_matches_operational_cases": all(
            comparison["match"] for comparison in comparisons
        ),
        "planet_index_cases_disjoint": len(set(PLANETS)) == len(PLANETS),
        "planet_index_cases_cover_named_and_other": all(
            summary_index(name) == index for index, name in enumerate(PLANETS)
        )
        and all(summary_index(value) == -1 for value in samples[len(PLANETS) :]),
        "between_indices_guards_cover_reachable_indices": all(
            (i < 0 or j < 0) or (i >= 0 and j >= 0 and (i < j or i >= j))
            for i in range(-1, 8)
            for j in range(-1, 8)
        ),
        "counterfactual_mutations_detected": all(
            witness["expected"] != witness["mutated"]
            for witness in mutation_witnesses.values()
        ),
    }
    report = {
        "checks": checks,
        "all_checks_pass": all(checks.values()),
        "source_ast_checks": ast_checks,
        "sample_count": len(comparisons),
        "mismatch_count": sum(not item["match"] for item in comparisons),
        "comparisons": comparisons,
        "counterfactual_mutation_witnesses": mutation_witnesses,
    }
    print(json.dumps(report, indent=2, sort_keys=True, ensure_ascii=False))
    if not report["all_checks_pass"]:
        raise SystemExit(1)


if __name__ == "__main__":
    main()

